/**
 * Per-service health for an environment.
 *
 * Honesty: this data is generated by Orrery's log simulator from the deployed
 * revision and a seeded PRNG. It is synthetic for EVERY provider — LocalStack
 * and AWS included — because no adapter reports real health yet. So the route
 * names the environment's actual provider rather than letting the UI assume
 * "sandbox", and `simulated` says plainly that nothing was measured.
 */
import { q } from "@/lib/db/store";
import { getProvider, providerRegistry } from "@/lib/providers/types";
import { logsimModule } from "@/lib/server/boot";
import { notFound, route } from "@/lib/server/context";

export const dynamic = "force-dynamic";

export const GET = route<{ envId: string }>(async (_req, { envId }) => {
  const env = q.environment(envId);
  if (!env) throw notFound(`Environment "${envId}"`, "Pick an environment from the project's Observe tab.");

  const providerId = q.connection(env.connectionId)?.provider ?? "sandbox";
  const provider = providerRegistry().has(providerId) ? getProvider(providerId) : undefined;
  const logsim = await logsimModule();

  return {
    environmentId: env.id,
    /**
     * True: nothing here was measured against running infrastructure.
     * When an adapter grows a real health check, this becomes
     * `!provider.reportsHealth` — the flag is on the wire either way.
     */
    simulated: true,
    /** who this environment actually deploys through, so nothing is misattributed */
    provider: { id: providerId, displayName: provider?.displayName ?? providerId },
    generatedBy: "Orrery's log simulator, from the deployed revision",
    services: logsim.environmentHealth?.(env.id) ?? {},
  };
});
